-- 08/11/2026 — Levânia, Ludgrim e Eredra: reino, cidades, locais e pessoas.
--
-- Usuário: "Faça mais reinos, cidades, deuses e demônios." Lote de 3 reinos
-- (ordem de tagmar/reinos.pdf, caps. 3.1–3.3, com tagmar/ambientacao.pdf),
-- escritos com a skill cronista-de-tagmar. Destino escolhido pelo usuário:
-- "Global e funde rascunhos" — o texto vai para o catálogo do mundo e os
-- rascunhos vazios destes reinos nas histórias 13 e 24 saem (nada aponta para
-- eles); o resumo que o Mestre escreveu na história 24 é preservado no global.
-- Nada daqui repete o que já existe em qualquer história (lição da correção de
-- duplicatas de Verrogar/Calco). Idempotente.

BEGIN;

-- ── levania ──

INSERT INTO public.reinos (slug, nome, resumo, descricao, governo, cultura, historia_recente, rumores, compartilhado) VALUES
($t$levania$t$, $t$Levânia$t$, $t$Reino de areia e de tribos antigas no oeste dos Reinos, repartido entre três Kaliafís que obedecem, ao menos no nome, ao Grande Kaliaf de Sadom.$t$, $t$A Levânia tem Abadom ao norte, o mar a oeste, Verrogar e Âmiem a leste e Ludgrim ao sul, separada deste pelo rio Aurim. Quase toda a terra é árida ou deserta, e no centro se abre o Deserto de Blirga, com o Campo Branco no meio. O sul e o leste, perto de Âmiem, são mais brandos, de pradarias e savanas, e a margem norte do Aurim é o chão mais fértil do reino. Ao norte, os Montes Moncurianos descem da Cordilheira de Sotopor até o mar, e a seus pés corre o Brual.
O povo é quase todo humano, de pele curtida pelo sol, e vive onde a água deixa: nas margens do Brual e do Aurim, nos oásis e na costa. Longe delas andam as tribos nômades, que montam e desmontam reinos de uma vida só.
O comércio é quase todo de costa. Sadom tem o maior porto, e por ela passam as rotas marítimas do oeste do Mundo Conhecido; Ingru tem o segundo e um artesanato que os mercadores de Plana preferem a qualquer outro. Beruni alimenta o reino com grãos, ovelhas e cabras, e os Montes Moncurianos começam a dar minério. Entre as três Kaliafís já não se cobra taxa sobre mercadoria, e as rotas por terra seguem difíceis.
Em Sadom cultuam-se sobretudo Ganis, Maira e Parom, e a devoção aos dois últimos cresceu depois da queda de Abadom; ali fica o maior templo de Maira Mon do reino. Em Sika erguem-se grandes templos a Blator e a seus filhos, e Crezir ganha devotos a cada estação. Em Ingru os templos mais numerosos são de Sevides, Maira e Selimom. Os milagres dos deuses são aceitos, como em toda Tagmar, mas nunca sem alguma apreensão.$t$, $t$O reino é monarquia só no nome. Três grandes tribos, as Kaliafís, dividem a terra: Moncuria ao norte, com capital em Sadom; Brual ao centro, com capital em Ingru; e Blirga ao sul, com capital em Sika, à beira do Aurim. Abaixo delas vivem tribos menores ligadas por parentesco e tribos nômades guiadas pelo patriarca, e o Grande Kaliaf, Líder de todas as Tribos, muitas vezes só manda de fato na própria capital. As cidades que dão filhas ou irmãs aos Kaliafs das capitais são chamadas cidades irmãs. A justiça é severa: os capitães da guarda resolvem quase tudo, e o culpado é julgado em praça pública, por aclamação do povo, diante do comandante da guarda, do Conselheiro da Justiça ou, em dia de festa, do próprio Kaliaf, que às vezes concede anistia. Só os vizires, linhagem de magos sob o Grão-vizir, dão licença para o uso da magia; quem a usa sem ela comete crime.
A nobreza leva se mede pelo sangue. Os Kaliafs das capitais, os líderes das cidades irmãs, os conselheiros e os vizires se ligam por casamentos que todos sabem recitar, e uma filha bem casada vale mais que um tratado. Hoje os três Kaliafs são parentes entre si, o que empurra as tribos para a unificação.$t$, $t$Os levas são quase todos humanos, descendentes das três grandes tribos que formaram o reino, e dão à linhagem um peso que os outros povos estranham. Muito de sua história se perdeu no tempo da Seita e sobrevive de boca em boca; há tribos que ainda recitam suas gerações de séculos atrás. É na Levânia que o malês tem mais dialetos, e até a nobreza custa a deixar a língua materna à mesa de negócios. A magia é vista como coisa profana: nas lendas levas, mago e demônio andam juntos, e as cidades que os acolheram acabaram engolidas pela areia.
Os levas guardam a história de boca em boca, e o leva, sua língua, partiu-se em tantos dialetos que nem o de Sadom, imposto como oficial, conseguiu juntá-los. A vida em Sadom é de arte e beleza, e sua grande biblioteca guarda o que restou do antigo acervo do reino.
Em dias de festa o próprio Kaliaf julga em praça pública, e é então que às vezes se perdoam presos por ordem real.$t$, $t$Os levas se fixaram nas terras férteis do Brual e do Aurim e fundaram Sadom em 180 D.C.; de todas as suas cidades, só ela tem raízes anteriores ao Grande Sábio. Por quase um milênio as cidades-estados viveram em paz sob um ancião-rei escolhido entre os sábios. Nos contatos de 420 D.C. com Abadom, Verrogar e a Moldânia, a Levânia recusou a união com os moldas e proclamou a superioridade dos levas. Em 1110 D.C. o clã sulista dos Bankdis já dominava pelos casamentos quase todo o reino, menos Sadom, que caiu em 1135. Em 1140 Ras'Zoul se fez imperador, os Bankdis assinaram o pacto que lhes vendia a alma, os sacerdotes arderam nas praças e nasceu a Seita; dali vieram a Fúria do Sul, os Treze Portões Antigos e a guerra que tomou Abadom e boa parte do mundo. Quando o Grande Sábio baniu os Senhores Infernais em 1405, os Bankdis recuaram e foram vencidos em sua própria terra em 1407. A Levânia entrou na grande coalizão dos reinos e, depois de 1450, voltou a governar a si mesma. Hoje as três Kaliafís caminham para a unificação, e o mundo teme que o trono caia nas mãos de Baruk, Kaliaf de Sika.
No tempo de hoje a Levânia se dá bem com os reinos. Calco tem laços estreitos com Sadom; Ingru, longe demais, e Sika, de ideias opostas, mantêm poucas relações. Verrogar comercia sem restrição com Sika, Plana busca o artesanato leva, e os magos de Portis têm embaixada em Rokor. Moham, o Grande Kaliaf, não tem herdeiro vivo: o mais provável é que o trono passe a Baruk, e o menos, a Olamar de Ingru.$t$, $t$Contam os levas que onde hoje está o Campo Branco havia uma grande cidade do Segundo Ciclo, soterrada sob o deserto branco com tesouros e magias que ninguém imagina.
Dizem que o povo leva chegou pelo mar. Ganis quis afogar os primeiros barcos, mas Blator, vendo que eram gente de guerra, salvou-os e os mandou a Sadom; por isso se chamam "povo de Sadom", que quer dizer "porto seguro".
Fala-se de um golpe de Baruk para tomar de assalto toda a Levânia. Ele já tem acordos e aliados em vários reinos, e é o ouro de Sika que reergue Altarape e paga a obra do porto de Ingru: uma saída para o mar, justamente o que Verrogar sempre quis.
Corre que Angrim, o filho de Moham que sumiu num navio a caminho de Calco, está vivo e voltará para liderar a Levânia unificada.
Na corte leva se murmura que o Kaliaf compra armas aos poucos dos mercadores de Plana e que tem planos para Ludgrim e Dartel. Quais, ninguém sabe.
Alguns eruditos dizem que a capital dos adoradores de demônios do fim do Segundo Ciclo ficava na Levânia, e que no cataclismo os deuses a destruíram, deixando o deserto como marca.$t$, false)
ON CONFLICT (slug) DO UPDATE SET descricao = EXCLUDED.descricao, governo = EXCLUDED.governo, cultura = EXCLUDED.cultura,
  historia_recente = EXCLUDED.historia_recente, rumores = EXCLUDED.rumores, resumo = EXCLUDED.resumo;

INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$rokor$t$, $t$Rokor$t$, $t$levania$t$, false, NULL, NULL, NULL, $t$Vive dos guias e rastreadores que vende às expedições e das grandes feiras abertas, onde se acham criaturas raras de muitas espécies.$t$, $t$Rokor é a cidade irmã de Sadom: a filha de seu líder, Amenasim, a Linda, é esposa do Grande Kaliaf Moham. É dali que parte quem tem coragem de enfrentar o deserto da Levânia, o Campo Branco, as brumas de Dartel ou as terras mortas de Abadom.
Seus rastreadores e guias conhecem cada trilha segura da areia, e muita expedição só voltou por causa deles. Os magos de Portis mantêm uma embaixada na cidade, de onde preparam viagens a Abadom e ao Sul do Mundo.$t$, NULL, false),
($t$ingru$t$, $t$Ingru$t$, $t$levania$t$, false, NULL, $t$Olamar$t$, $t$Sevides, Maira e Selimom têm a maior parte dos templos; o Kaliaf Olamar mantém em seu castelo um templo dedicado a Lena.$t$, $t$Manufatura e artesanato, o mais procurado pelos mercadores de Plana; tem o segundo maior porto do reino, comércio direto com Plana e Portis e as primeiras minas dos Montes Moncurianos.$t$, $t$Ingru é a capital da Kaliafís de Brual e uma das pérolas da costa leva, perto de onde o rio Brual desemboca no mar. Fica entre as tribos do norte e as do sul, e por isso é a mais cosmopolita das cidades do reino: seus mercadores negociam em todas as frentes.
Suas peças de artesanato são tidas como obras-primas de raro bom gosto e garantem a renda da cidade. Dos três reinos tribais, é o que tem menos problemas entre o povo.
O Kaliaf Olamar, porém, governa de longe e deixa as decisões nas mãos de seus conselheiros, sobretudo do Conselheiro da Justiça, Jalil Abemerim, cunhado de Baruk de Sika. Por isso Ingru mantém relações estreitas com poucos reinos e já sente a mão de Sika sobre si.$t$, $t$Dizem que é o ouro de Sika que paga a obra do porto de Ingru, e que Baruk quer com ele a saída para o mar que Verrogar tanto desejou.$t$, false),
($t$dameste$t$, $t$Dameste$t$, $t$levania$t$, false, NULL, NULL, $t$Templos aos mais diversos deuses adorados na Levânia, alguns com quase mil anos.$t$, NULL, $t$Dameste é a cidade irmã de Ingru e, para muitos, uma cidade santa, procurada por quem busca paz de espírito e o saber dos deuses. Leva o nome do sábio que foi o primeiro ancião-rei da Levânia.
É tida como terra neutra e abriga a única parte não humana da população do reino. Seus templos, erguidos há quase mil anos, são contados entre as maravilhas de pedra do Mundo Conhecido.
A bela Lilandi Almiscaris, esposa do Kaliaf Olamar, é irmã de um dos líderes da cidade.$t$, NULL, false),
($t$sika$t$, $t$Sika$t$, $t$levania$t$, false, NULL, $t$Baruk$t$, $t$Grandes templos de Blator e de seus filhos; o culto a Crezir cresce depressa entre o povo.$t$, $t$Cidade de armas: sustenta um exército crescente e mantém comércio sem restrições com Verrogar.$t$, $t$Sika é a capital da Kaliafís de Blirga, banhada pelo rio Aurim, e hoje vive sob o punho de ferro do Kaliaf Baruk. Das três grandes tribos, a de Blirga sempre foi a mais ortodoxa e fanática, e Sika acolheu sem resistência o nacionalismo guerreiro e a exclusão de raças que vêm de Verrogar.
Os jovens se alistam aos catorze ou quinze anos e passam seis ou sete em treinamento, e Baruk recruta também entre as tribos nômades. Poucos reinos têm hoje um exército que cause tanta inveja.
A justiça de Sika é famosa pela crueldade: mãos decepadas, ferro em brasa, açoite e forca em praça pública, e, nos últimos anos, empalamentos com os corpos expostos depois da morte. As boas relações de Beruni com Âmiem e Ludgrim incomodam a cidade, que só se entende bem com Verrogar.
Se Baruk chegar a Grande Kaliaf, Sika passará a ser a capital da Levânia.$t$, $t$Dizem que Baruk quer declarar guerra a Ludgrim assim que tiver o trono, e que essa guerra incendiaria todo o sul de Tagmar.$t$, false),
($t$beruni$t$, $t$Beruni$t$, $t$levania$t$, false, NULL, NULL, NULL, $t$O maior centro de lavoura e criação da Levânia: grãos, legumes, ovelhas e cabras que abastecem o reino há séculos.$t$, $t$Beruni é a cidade irmã de Sika: Meline Flor do Deserto, filha de seu líder, é esposa do Kaliaf Baruk. Fica na margem norte do rio Aurim, na terra mais fértil do reino, perto de uma floresta de tamanho espantoso para uma região tão seca. Dizem que ali a Levânia ainda é o que era milhares de anos atrás, antes de existir.
Há séculos alimenta todo o reino, e pesa nas decisões das tribos; no passado, muitos de seus líderes chegaram a Kaliaf de Sika. Hoje está sob o domínio de Baruk.
Mantém ótimas relações com Âmiem e Ludgrim, o que causa desgosto em Sika.$t$, NULL, false),
($t$altarape$t$, $t$Altarape$t$, $t$levania$t$, false, NULL, $t$Sarrimede Daruim$t$, NULL, NULL, $t$Altarape foi a joia do deserto, tida por todo leva como a mais bela de suas cidades, lugar de cultura e entendimento; ainda hoje se compara Sadom a ela. Ficou perdida nas areias e foi achada há pouco, em ruínas, entre Sika e Beruni, bem ao norte, perto do Campo Branco.
Está sendo reerguida com o ouro de Sika e governada pelo vizir Sarrimede Daruim, posto ali por decreto de Baruk. É a primeira vez na história leva que um vizir se torna senhor de uma cidade.$t$, $t$Dizem que em Altarape se escondem pergaminhos de magias antigas e o saber de ervas capazes de verdadeiros milagres, de antes de a Levânia virar deserto.$t$, false),
($t$filhos-da-terra$t$, $t$Filhos da Terra$t$, $t$levania$t$, false, NULL, NULL, $t$Sevides é o patrono do povoado.$t$, $t$Cultiva a edisselia, planta que só ali se conhece, ingrediente da poção Vigor de Sevides.$t$, $t$Filhos da Terra é um povoado antigo a leste do Campo Branco, longe das grandes cidades, consagrado a Sevides.
Seu povo cultiva a edisselia, planta única com que se prepara o Vigor de Sevides. Quem bebe a poção ganha forças para aguentar o deserto e trabalhar a terra o bastante para viver dela.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$deserto-de-blirga$t$, $t$Deserto de Blirga$t$, $t$levania$t$, NULL, $t$O Deserto de Blirga ocupa o centro da Levânia e dá nome à Kaliafís do sul. É deserto quente: o dia queima e a noite gela. No seu meio fica o Campo Branco.
Foi para ele que Alevos, chefe dos Bankdis, se retirou para orar ao deus da guerra e da fúria, e de lá voltou prometendo a vitória que deu origem à Seita. Em suas areias acharam-se pergaminhos com canções do começo do Terceiro Ciclo, escritos por cima de textos mais antigos do profeta Arquidecira.$t$, $t$Dizem que o deserto nasceu há uns mil anos, por volta de 500 D.C., de uma maldição de Maira contra os povos que devastaram a terra.
No sul, na tribo de Blirga, contam outra coisa: que uma grande batalha contra um antigo rei feiticeiro terminou numa explosão que matou tudo e deixou o deserto e o Campo Branco.
Outros juram que o clima da Levânia sempre foi assim, e que só o Campo Branco é obra de guerra.$t$, false),
($t$campo-branco$t$, $t$Campo Branco$t$, $t$levania$t$, NULL, $t$O nome engana: o Campo Branco não é planície nevada nem lugar de paz. É um trecho no interior do Deserto de Blirga, de umas duas léguas de norte a sul e pouco mais de uma de leste a oeste, coberto só de ossos — de anões, elfos, humanos e de raças de que ninguém tem notícia.
Não se vê ali construção alguma, embora haja relatos de escadarias que descem a labirintos sem fim. Os registros do lugar vêm desde a Unificação do Grande Sábio, e os ossos continuam intactos, como se o vento, a areia e os anos não os tocassem; por isso se crê que seja lugar de magia, e o clima em volta não segue as regras do resto do deserto.
A região é tida como segura, mas muita gente lhe tem pavor. A cautela, dizem os guias, é boa companheira da dúvida.$t$, $t$Contam histórias de legiões de esqueletos que se levantam ali e travam combates que nunca acabam.
Dizem que sob os ossos dorme uma grande cidade do Segundo Ciclo, com tesouros e magias poderosíssimas.
Foi ao Campo Branco que uma tempestade de areia levou Alevos, perseguido por uma voz em sua mente, antes da vitória dos Bankdis.$t$, false),
($t$montes-moncurianos$t$, $t$Montes Moncurianos$t$, $t$levania$t$, NULL, $t$Os Montes Moncurianos partem da Cordilheira de Sotopor e correm até o mar, a oeste, com picos tão altos e famosos quanto os dela. O vale do rio Brual os corta, e é a seus pés que o rio desce até Ingru.
Ainda são pouco explorados, mas já se mostram boa fonte de minério: Ingru começou a extraí-lo, e Sika passa a querer mais. Nas cavernas perto do Deserto de Blirga vivem bichos raros, como o escorpião gigante negro.$t$, NULL, false),
($t$rio-brual$t$, $t$Rio Brual$t$, $t$levania$t$, NULL, $t$O Brual nasce nas cordilheiras, corre ao pé dos Montes Moncurianos e desemboca no mar perto de Ingru. Marca a fronteira entre a Kaliafís de Moncuria, ao norte, e a de Brual, que leva seu nome.
Suas margens férteis foram dos primeiros lugares onde os levas se fixaram, e a defesa delas uniu as cidades por quase um milênio.$t$, NULL, false),
($t$rio-aurim$t$, $t$Rio Aurim$t$, $t$levania$t$, NULL, $t$O Aurim é a fronteira natural entre a Levânia e Ludgrim. Sua margem norte é a terra mais fértil do reino, e nela ficam Sika e Beruni.
No tempo antigo, quem controlava o Aurim controlava o pão dos levas, e foi assim que os Bankdis ganharam força. Foi também às suas margens que Alevos reapareceu, depois de duas semanas sumido no Campo Branco, sorrindo e prometendo a vitória.$t$, NULL, false),
($t$montanhas-xarar$t$, $t$Montanhas Xarar$t$, $t$levania$t$, NULL, $t$As Montanhas Xarar fazem a fronteira entre Âmiem, Levânia e Ludgrim. O inverno ali é duro, de nevascas constantes.
No sopé crescem os pomares de candre, noz que, moída, dá uma farinha fina para massas leves e folhadas, muito usada na cozinha dos elfos.$t$, $t$Conta-se uma história sombria: o bloco de cristal em que o demônio Morrigalti foi aprisionado estaria escondido numa das cavernas dessas montanhas.$t$, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$moham$t$, $t$Moham, o Alto Iluminado e Grandioso$t$, $t$Humano$t$, $t$Grande Kaliaf da Levânia$t$, NULL, $t$O mais velho dos três Kaliafs$t$, $t$levania$t$, $t$sadom$t$, $t$Moham é o Grande Kaliaf de Sadom e senhor de toda a Levânia, escolhido antes de Baruk chegar a Kaliaf. Depois da morte do pai foi estudar em Calco, e de lá trouxe o saber sobre a história e os costumes dos outros reinos; é a ele que Sadom deve a prisão-sem-muros, em que o condenado trabalha mas não pode se afastar da cidade e se apresenta sempre à guarda.
É homem justo e conhece bem o perigo do fanatismo de fé e de raça que começa a tomar a Levânia. É casado com Amenasim, a Linda, filha do líder de Rokor.
O desaparecimento de seu filho Angrim foi um golpe duro, e sem herdeiros vivos o trono deve passar a outro quando ele morrer.$t$, $t$Correm vozes de que a perda de Angrim seria uma farsa, armada para manter o menino a salvo. Quem sabe a verdade, ninguém diz.$t$, false),
($t$mardeil_narmamuk$t$, $t$Mardeil Narmamuk$t$, $t$Humano$t$, $t$Grão-vizir da Levânia$t$, NULL, $t$Barba já grisalha$t$, $t$levania$t$, $t$sadom$t$, $t$Mardeil é o mais alto dos vizires e o braço direito do Grande Kaliaf, responsável por fiscalizar e licenciar toda a magia do reino. É de estatura pequena e porte nobre, com a barba sempre bem aparada.
Gozava da confiança do pai de Moham, cuidou dos estudos do jovem em Calco e foi um dos que mais trabalharam por sua escolha como Grande Kaliaf. Foi ele também quem preparou a viagem de Angrim para Calco, e a perda do menino abalou a confiança que Moham tinha nele.$t$, NULL, false),
($t$amenasim$t$, $t$Amenasim, a Linda$t$, $t$Humano$t$, $t$Esposa do Grande Kaliaf$t$, NULL, NULL, $t$levania$t$, NULL, $t$Amenasim, a quem chamam a Linda, é filha do líder de Rokor e esposa do Grande Kaliaf Moham. É por esse casamento que Rokor é a cidade irmã de Sadom.
É a mãe de Angrim, o herdeiro desaparecido.$t$, NULL, false),
($t$angrim$t$, $t$Angrim$t$, $t$Humano$t$, $t$Herdeiro desaparecido de Sadom$t$, NULL, NULL, $t$levania$t$, NULL, $t$Angrim é o filho de Moham e Amenasim. Ainda menino, embarcou num navio de passageiros para Calco, onde começaria os estudos, e nunca chegou.$t$, $t$Dizem que está vivo e que logo voltará para liderar a Levânia unificada.
Outros dizem que o próprio pai fingiu sua perda para escondê-lo dos inimigos.$t$, false),
($t$olamar$t$, $t$Olamar$t$, $t$Humano$t$, $t$Kaliaf de Ingru$t$, $t$Lena$t$, $t$Velho; chamam-no "o velho"$t$, $t$levania$t$, $t$ingru$t$, $t$Olamar, a quem todos chamam "o velho", é o Kaliaf de Ingru e o único ainda vivo do tempo em que se escolheu o Grande Kaliaf. Serviu ao pai de Moham e mantém em seu castelo um templo dedicado a Lena.
É casado com a bela Lilandi Almiscaris, irmã de um dos líderes de Dameste. Tem fama de líder relapso, que deixa as ordens e as funções do governo aos conselheiros e ao vizir, sobretudo ao Conselheiro da Justiça, Jalil.
Ainda assim é homem muito sábio, e tem ido muitas vezes a Sadom aconselhar-se com Moham. Foi sua intervenção que impediu boa parte das sentenças de morte de Jalil.$t$, $t$Dizem que a apatia de Olamar diante da própria Kaliafís é obra das tramas de Baruk.$t$, false),
($t$lilandi_almiscaris$t$, $t$Lilandi Almiscaris$t$, $t$Humano$t$, $t$Esposa do Kaliaf de Ingru$t$, NULL, NULL, $t$levania$t$, $t$ingru$t$, $t$A bela senhora Lilandi Almiscaris é esposa do Kaliaf Olamar e irmã de um dos líderes de Dameste, o que faz desta a cidade irmã de Ingru. Seu pai, já morto, descendia de um dos Grandes Kaliafs do passado.$t$, NULL, false),
($t$jalil_abemerim$t$, $t$Jalil Abemerim$t$, $t$Humano$t$, $t$Conselheiro da Justiça de Ingru$t$, NULL, NULL, $t$levania$t$, $t$ingru$t$, $t$Jalil é o Conselheiro da Justiça do Kaliaf Olamar, o segundo cargo de Ingru depois do vizir, e é casado com a irmã de Baruk. É homem duro e sem honra, capaz de grandes atrocidades; se Olamar não o contivesse, muitas sentenças de morte já teriam saído de suas mãos.
Sua subida rápida ao cargo é vista como jogada de Baruk sobre Olamar.$t$, $t$Com a morte de Olamar parecendo próxima, já se diz que Jalil será o novo Kaliaf de Ingru, e que isso abrirá um tempo sombrio para a Levânia.$t$, false),
($t$baruk$t$, $t$Baruk$t$, $t$Humano$t$, $t$Kaliaf de Sika$t$, NULL, NULL, $t$levania$t$, $t$sika$t$, $t$Baruk é filho do guerreiro Barukar, antigo Grande Kaliaf, e chegou a Kaliaf de Sika quando o pai morreu, de modo ainda mal explicado ao povo, pouco depois da escolha de Moham. É casado com Meline Flor do Deserto, filha do líder de Beruni.
Guerreiro enérgico e poderoso, formou-se numa das academias de Verrogar e é aberto às ideias daquele reino. Aos poucos reúne um exército capaz, sozinho, de arrastar boa parte do mundo para a guerra.
Já tem grande influência em Ingru e domina Beruni e Altarape. Como Moham não tem herdeiros vivos, é o mais provável sucessor ao trono das tribos, e o mais temido.$t$, $t$Dizem que prepara um golpe para tomar a Levânia de assalto e que, uma vez Grande Kaliaf, declarará guerra a Ludgrim.$t$, false),
($t$meline_flor_do_deserto$t$, $t$Meline Flor do Deserto$t$, $t$Humano$t$, $t$Esposa do Kaliaf de Sika$t$, NULL, NULL, $t$levania$t$, NULL, $t$Meline, chamada Flor do Deserto, é filha do líder de Beruni e esposa do Kaliaf Baruk. É por ela que Beruni é a cidade irmã de Sika.$t$, NULL, false),
($t$barukar$t$, $t$Barukar$t$, $t$Humano$t$, $t$Antigo Grande Kaliaf$t$, NULL, NULL, $t$levania$t$, NULL, $t$Barukar foi guerreiro e Grande Kaliaf no passado, e é pai de Baruk de Sika. Morreu pouco depois da escolha de Moham, de modo que o povo até hoje não entende bem.$t$, NULL, false),
($t$sarrimede_daruim$t$, $t$Sarrimede Daruim$t$, $t$Humano$t$, $t$Vizir, senhor de Altarape$t$, NULL, NULL, $t$levania$t$, $t$altarape$t$, $t$Sarrimede é vizir da linhagem da Kaliafís de Blirga e senhor de Altarape por decreto de Baruk, o primeiro vizir em toda a história leva a governar uma cidade. É primo em segundo grau de Baruk e o único de sua família que nasceu com poder arcano.
Fala pouco, mas sua influência política é grande, e todos o temem como um dos vizires mais poderosos do reino.$t$, NULL, false),
($t$alevos$t$, $t$Alevos$t$, $t$Humano$t$, $t$Antigo líder dos Bankdis$t$, NULL, NULL, $t$levania$t$, NULL, $t$Alevos chefiava o clã dos Bankdis quando estes já dominavam quase toda a Levânia, menos Sadom. Retirou-se ao Deserto de Blirga para orar à divindade da guerra e da fúria, e uma tempestade de areia o levou ao Campo Branco, onde uma voz o perseguiu em pensamento.
Duas semanas depois seus homens o acharam às margens do Aurim, sorrindo e jurando a vitória: a Levânia só seria deles com Sadom, e ele tinha um trunfo que a garantiria mesmo depois de sua morte. Morreu com a guerra no trigésimo ano e passou o segredo ao filho, Ras'Zoul.$t$, NULL, false),
($t$ras_zoul$t$, $t$Ras'Zoul$t$, $t$Humano$t$, $t$Imperador da Levânia e fundador da Seita$t$, NULL, NULL, $t$levania$t$, NULL, $t$Ras'Zoul, filho de Alevos, era mago poderoso. No cerco a Sadom sumiu por três meses e voltou à frente de monstros e feras do extremo sul, com os quais tomou a cidade em 1135 D.C.
Em 1140 se fez imperador e chamou cerca de vinte mil levas do clã a assinar o Pacto dos Bankdis, que entregava suas almas ao poder que lhes dera a vitória. Vieram então o expurgo dos deuses, os sacerdotes queimados nas praças e a Seita.$t$, NULL, false),
($t$azaldim_iv$t$, $t$Azaldim IV$t$, $t$Humano$t$, $t$Ancião-rei da Levânia$t$, NULL, NULL, $t$levania$t$, NULL, $t$Azaldim IV foi ancião-rei da Levânia no tempo em que os Bankdis cresciam. Temendo que dominassem o reino inteiro, aconselhou o rei de Sadom a casar a filha com o príncipe de Abadom, em vez de entregá-la a um Bankdi.
Os sadonianos não gostaram da união, mas a aceitaram. Enquanto a princesa partia para o norte, tropas se juntavam às margens do Aurim.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

UPDATE public.reinos SET capital = $t$sadom$t$ WHERE slug = $t$levania$t$;



-- ── ludgrim ──

INSERT INTO public.reinos (slug, nome, resumo, descricao, governo, cultura, historia_recente, rumores, compartilhado) VALUES
($t$ludgrim$t$, $t$Ludgrim$t$, $t$Reino meridional de florestas, neblina e invernos de neve, nascido da aliança entre homens, meio-elfos e elfos, e hoje a maior terra de meio-elfos do Mundo Conhecido.$t$, $t$Ludgrim é um dos maiores reinos do Mundo Conhecido e o mais meridional dos Reinos Civilizados. Ao norte faz fronteira com a Levânia e com o reino élfico de Âmiem, separado deles pelas Montanhas Xarar; a leste com Eredra; a oeste com o Mar do Afogado; e ao sul com as Terras Selvagens e a cadeia das Montanhas Morânicas. Quase todo o reino assenta sobre serras altas, e por isso é o mais frio dos Reinos: o verão é fresco, e o inverno congela rios e lagos e traz neve todos os anos.
As florestas são muitas e as comunidades poucas, espalhadas pelas beiradas das matas e pelos vales. Siltam, Kender e Tambar são as grandes florestas do reino, e o rio Darniar o atravessa de ponta a ponta desde as Morânicas. À tarde, quando o sol começa a baixar, a neblina sobe do chão nas terras baixas; fora das estradas o mato é tão denso e o caminho tão sinuoso que os viajantes avançam pouco mais depressa que um homem a pé.
A riqueza do reino vem do excedente das lavouras, plantadas em volta das cidades. A terra dá legumes de raiz bulbosa, e as beterrabas de folha verde e bulbo vermelho-escuro chegam a pesar umas dez libras; são a base da cozinha local. Também pesam no comércio as especiarias usadas em poções e ritos, como o peixe pigi do rio Galatel, e os instrumentos musicais dos artesãos de Ludgrim, que alcançam preços altíssimos em terras distantes como Conti e Calco. O reino abre estradas e explora minas novas nas montanhas; a mais nova das estradas, a Estrada do Rei, liga Donatar à cidade de Tanue, em Eredra.
Selimom é o deus mais amado do reino. A Ordem do Alvorecer, a maior de suas ordens sacerdotais, teria sua casa a noroeste da capital, e Donatar guarda uma grande catedral ao Deus da Paz, de torres de mármore lavradas por mestres élficos. Palier tem culto forte na capital e nas vilas vizinhas das comunidades élficas; Sevides é lembrado pelas boas colheitas dos últimos anos; Maira Vet recebe preces em toda parte, porque suas florestas estão sempre à vista. Crizagom, o Deus da Honra, é o deus da nobreza e do exército.$t$, $t$Ludgrim é uma monarquia, e a palavra do rei é lei. O rei Darniar, meio-elfo e filho do fundador Eredil, governa porém com um conselho em que cada membro cuida de um aspecto do reino. Antes de decidir, o rei escuta o conselho, e raras vezes sua decisão foi contrária à da maioria.
O conselho é liderado pelo Conselheiro-Mor, cargo de Nidal, elfo dourado de Âmiem que serve à Coroa desde a fundação. Cabe a ele também tratar com os reinos vizinhos, negociar rotas de comércio e guardar os interesses de Ludgrim em terras estrangeiras.
As cidades menores têm seus próprios senhores, como o Barão Randal em Serfa e o alcaide de Balinor. A província élfica de Guaimbar, na Floresta de Siltam, tem leis e fronteiras próprias, julga seus elfos junto com o rei e mantém ao menos uma cadeira permanente no conselho.
Quem toma a paz do reino por fraqueza se engana: Ludgrim tem um grande exército, que patrulha as fronteiras e conta com os melhores arqueiros não élficos de Tagmar. O alistamento é obrigatório para todos, menos para os elfos. As maiores praças militares são Agrimir, nascida do Grande Forte, e o Forte Galatel.$t$, $t$A maior parte do povo é de meio-elfos, descendentes dos primeiros encontros entre as duas raças; Ludgrim abriga a maior população deles no Mundo Conhecido, e muitos vêm de longe só para conhecer a terra de sua gente. Os humanos são numerosos e estão por toda parte. Elfos aparecem vez ou outra fora de suas comunidades, vivendo como sábios ou artesãos nas vilas afastadas.
Os pequeninos não têm vila própria, mas se acham nas cidades grandes e sobretudo nas fazendas em volta da capital, onde vendem um fumo afamado. Os anões têm uma colônia na parte leste das Montanhas Morânicas e são tidos por cidadãos do reino; nas vilas trabalham como ferreiros ou se alugam como mercenários. Entre eles corre o dito: "A cerveja de Abrasil, a perrita de Dantsem e o fumo de Ludgrim: os pequeninos, sem saberem, já conquistaram Tagmar."
Os ludgrianos gozam de uma liberdade rara no sul. Qualquer ofício pode ser praticado e honrado, os estrangeiros são bem recebidos e todas as fés são respeitadas. A escravidão existe só como pena do Estado, por crime ou por dívida, e apenas a Coroa pode ter escravos; os servos das casas nobres e ricas ficam sob a vigilância do governo contra os abusos. Nobres e soldados, devotos de Crizagom, têm fama de estar entre os mais honrados de Tagmar, talvez atrás apenas dos homens de Azanti.
A influência élfica fez do ludgriano um povo instruído nas artes místicas: poucos lançam feitiços, mas quase todos entendem o que se passa quando um mago o faz, e sabem que a magia não é boa nem má. Ainda assim, o mago é visto como alguém diferente, capaz de sumir da frente de qualquer um. A lei permite a magia a quem não fere a lei nem o próximo.
A língua do reino é o Malês, e nas comunidades humanas predomina o Malês meridional; elfos, anões e pequeninos guardam suas próprias línguas. O lud, fala nascida do convívio entre sulistas e elfos, foi unificado no tempo de Eredil por conselho de Nidal.$t$, $t$Há muito tempo os elfos eram numerosos no sul, e os homens que desciam para lá encontraram povos desconfiados, que arrasaram muitas de suas vilas por julgá-los barulhentos e destruidores de árvores. Algumas vilas resistiram, unidas a elfos renegados, e dessa união nasceram os primeiros meio-elfos de Tagmar, a quem os elfos chamavam mestiços.
Por volta de 1100 D.C. as tribos de orcos das Morânicas avançaram e destruíram as vilas élficas do sul. Em 1112 D.C., com os orcos já ao norte do rio Odem e prestes a atacar Siltam, homens e mestiços ofereceram aliança aos elfos, e o príncipe Donatar convenceu os seus a aceitá-la. Os exércitos de Donatar e de Eredil cercaram os orcos nas ruínas de Eldair, no Vale de Sumuta, durante um inverno inteiro, e na primavera de 1114 D.C. os venceram, ao preço da vida do príncipe.
Em 1116 D.C. as tribos humanas e mestiças fizeram de Eredil seu líder e fundaram Ludgrim, nome que na língua nativa quer dizer União. No mesmo ano firmou-se o acordo com os elfos de Siltam, mediado pela rainha Enora de Âmiem, e menos de três anos depois Eredil foi coroado na nova capital, Donatar. Seguiram-se cerca de trinta anos de paz.
Em 1145 D.C. chegaram do norte os pregadores Bankdis, que dividiram o povo e ganharam adeptos até na corte. Em 1150 D.C. foram ao sul selvagem recrutar orcos, trols e ogros, e em 1157 D.C. tomaram Donatar e escravizaram o reino; é o tempo que os sábios do norte chamam a Fúria do Sul. O rei e os elfos e meio-elfos que escaparam resistiram nas florestas de Siltam por duzentos e cinquenta anos, até que o Mais Sábio os procurou em 1402 D.C.; em 1407 D.C. as bestas foram expulsas e os Bankdis massacrados.
O reino saiu da guerra em escombros, com o povo reduzido, o gado morto, os campos estéreis e as doenças correndo como fogo em mato seco. Com o tempo e a teimosia de seu povo, reergueu-se. Hoje vive dias de prosperidade sob Darniar, que sucedeu ao pai: abrem-se estradas e minas, e a fama do rei facilita o comércio.
A paz, porém, tem sombra ao norte. Mais que os bárbaros e orcos do sul, preocupam o rei as intenções cada vez mais claras da corte de Verrogar. Boa parte das tropas está pronta para marchar caso Âmiem precise de socorro, pois, além de ser povo amigo, se a floresta dos nobres dourados cair, Ludgrim será o próximo alvo. Dentro do reino, as colônias agrícolas que avançam sobre as florestas ameaçam irritar os vizinhos, sobretudo os elfos.$t$, $t$Dizem que a tropa enviada pelo rei para investigar os sumiços na Floresta de Tambar já devia ter voltado há quase quinze dias, e que ninguém em Donatar sabe dizer onde ela está.
Corre na corte da Levânia que o rei levanino compra armas aos mercadores de Plana com planos para Ludgrim; quais, ninguém sabe.
Os bardos do sul cantam que a Espada de Meriam, arma de grande poder, jaz escondida em alguma das velhas florestas élficas do reino, Siltam ou Kender.
Há quem diga que, se a floresta dos nobres dourados de Âmiem cair diante de Verrogar, Ludgrim será a próxima, e que o rei Darniar já conta os dias para essa guerra.$t$, false)
ON CONFLICT (slug) DO UPDATE SET descricao = EXCLUDED.descricao, governo = EXCLUDED.governo, cultura = EXCLUDED.cultura,
  historia_recente = EXCLUDED.historia_recente, rumores = EXCLUDED.rumores, resumo = EXCLUDED.resumo;

INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$donatar$t$, $t$Donatar$t$, $t$ludgrim$t$, true, NULL, $t$Rei Darniar$t$, $t$Selimom acima de todos, com sua grande catedral na seção leste; Palier tem culto forte na capital.$t$, $t$Lã de ovelha de ótima qualidade, a lavoura do Celeiro, o comércio do Bairro dos Comerciantes e o fumo das fazendas dos pequeninos em volta da cidade.$t$, $t$Donatar, a capital, chamada a Pérola do Sul, leva o nome do príncipe élfico que morreu na guerra contra os orcos. É famosa pela lã de suas ovelhas e por uma arquitetura que junta o melhor de elfos e homens: casas quase todas térreas, misturadas à vegetação farta, com janelas grandes em arco e entalhes tão finos que prendem o olhar de quem passa. As ruas são cobertas de brita, para que as chuvas fortes da região não as façam lamaçal.
A cidade se divide em quatro seções. Ao norte fica a Seção Nobre, com o Castelo Real, onde moram o rei e a corte, e as mansões dos nobres que visitam a capital; ali estão as melhores tabernas, ferreiros e ourives, a preços que poucos pagam, e a maior guarda da cidade. No centro, o Bairro dos Comerciantes é onde se conserta a armadura, se compra mantimento para a estrada e se passa a noite na taberna; bem vigiado de dia, é bom lugar para gatunos depois do anoitecer.
Ao sul fica o Celeiro, onde estão as fazendas da capital e de onde sai tudo o que ela colhe. A seção leste guarda os prédios do governo, a catedral de Selimom, a biblioteca central e a sede da milícia. A Estrada do Rei parte de Donatar rumo a Tanue, em Eredra.$t$, NULL, false),
($t$grima$t$, $t$Grima$t$, $t$ludgrim$t$, false, NULL, NULL, NULL, $t$Porto marítimo; daqui partem navios para outras cidades da costa, sobretudo as da Levânia.$t$, $t$Grima, no oeste do reino, é o grande porto de Ludgrim. Suas docas foram ampliadas há pouco para receber mais navios, e daqui partem embarcações para várias cidades da costa, sobretudo as da Levânia.
Como todo porto, sofre com ladrões e assassinos, e mantém muitos soldados nas ruas, o que nem sempre os detém. Tabernas há às dezenas; as mais conhecidas são O Refúgio do Náufrago e O Punhal Esquecido.$t$, $t$Dizem que em Grima vive uma das guildas de assassinos mais temidas do reino, conhecida no submundo como a Guilda do Punhal Negro. Seria ela a responsável pela morte de muita gente importante da cidade, nobres inclusive, e há quem jure que seus serviços já foram contratados de fora do reino.$t$, false),
($t$serfa$t$, $t$Serfa$t$, $t$ludgrim$t$, false, NULL, $t$Barão Randal$t$, NULL, $t$Comércio intenso à beira da Estrada do Rei, que tem trazido bom lucro aos moradores.$t$, $t$Serfa nasceu do crescimento do próprio reino: à beira da Estrada do Rei, formou-se com os trabalhadores que foram ficando pelo caminho enquanto ela era aberta. Hoje tem comércio intenso, e seus moradores ganham bem com ele.
A cidade, porém, vive dias difíceis. A filha do Barão Randal, que governa Serfa, sofre de uma doença terrível: o corpo definha e a vida parece querer deixá-la. Médicos, curandeiros e sacerdotes já a examinaram, e nenhum descobriu de onde vem o mal.$t$, $t$Contam que a doença da filha do Barão Randal é maldição de uma antiga amante do barão, que depois de abandonada se fez maga e jurou vingança.$t$, false),
($t$timor$t$, $t$Vila Timor$t$, $t$ludgrim$t$, false, NULL, NULL, NULL, $t$Destila o meelbernil, licor das frutas meelberne das colinas de Cartã.$t$, $t$Timor é uma vila isolada, junto às colinas de Cartã, onde crescem os arbustos espinhosos da meelberne, fruta que não nasce em nenhum outro lugar. Os moradores destilam seu suco e fazem o meelbernil.
A bebida é amarga e tem fama de relaxar a garganta e suavizar a voz. A maioria dos estrangeiros que não são elfos despreza seu gosto refinado, mas os bardos de toda parte a procuram.$t$, NULL, false),
($t$balinor$t$, $t$Balinor$t$, $t$ludgrim$t$, false, NULL, NULL, NULL, $t$Revende, a preço alto, as peças forjadas pelos anões das montanhas próximas.$t$, $t$Balinor foi uma vila próspera e já é tida por pequena cidade. Fica no centro do reino, num vale entre montanhas, entre o rio Galatel e as florestas de Siltam.
O alcaide fez há pouco uma aliança com os anões da região, e a cidade tem lucrado muito com ela: seus moradores atravessam as montanhas com escolta reforçada e vendem com facilidade, e caro, o que os anões forjam.$t$, NULL, false),
($t$agrimir$t$, $t$Agrimir$t$, $t$ludgrim$t$, false, NULL, NULL, NULL, $t$Subsistência; o comércio é pequeno por causa da distância das outras cidades.$t$, $t$Agrimir, no sul do reino, perto da fronteira com as Terras Selvagens, é a cidade mais isolada de Ludgrim. Nasceu como o Grande Forte, que Eredil mandou erguer ao ser aclamado rei, para que o reino não fosse mais surpreendido por bestas vindas do sul como na Fúria do Sul.
Para lá foram mais de quinhentos soldados sob o comando de Agrimir, cada um com licença para levar a esposa. Vieram filhos e netos, e em pouco tempo a gente do forte triplicou. Ergueu-se então um muro sólido em volta da fortificação, e o Grande Forte virou cidade, com o nome de seu primeiro morador.
Hoje vive do que planta, longe de tudo. Ainda assim é refúgio seguro para viajantes e aventureiros que cruzam a região.$t$, $t$Os camponeses de Agrimir ainda contam dos ciclopes que desciam do sul antes de se erguer a Muralha de Goguistá.$t$, false),
($t$guaimbar$t$, $t$Guaimbar$t$, $t$ludgrim$t$, false, NULL, NULL, NULL, NULL, $t$Guaimbar é a província élfica da Floresta de Siltam: uma cidade dos elfos com leis e fronteiras próprias, cujos moradores são cidadãos de Ludgrim. Os transgressores elfos podem ser detidos por qualquer autoridade do reino, mas só as autoridades da própria cidade e o rei os julgam, e os elfos da província têm ao menos uma cadeira permanente no conselho.
Cada elfo de Guaimbar, ao chegar à idade madura, escolhe quantos dos deveres do reino quer assumir, e perde os direitos que andam com os deveres recusados. Quem não serve no exército, por exemplo, não pode guardar fronteira nem floresta por soldo, nem portar armas em cerimônia oficial.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-siltam$t$, $t$Floresta de Siltam$t$, $t$ludgrim$t$, NULL, $t$As florestas de Siltam, chamadas o Último Refúgio dos elfos, ainda são o lar dos elfos de Ludgrim. Depois da guerra contra os orcos, os sobreviventes se uniram ali sob Galadriom, numa comunidade aberta a todo elfo de qualquer origem, menos os sombrios. Pelo acordo de 1116 D.C., nenhum homem ou meio-elfo entra na floresta sem permissão dos elfos, e as duas partes se devem socorro em caso de invasão. Foi em Siltam que o rei e os fiéis à Coroa resistiram aos Bankdis por dois séculos e meio.
Os elfos zelam pela privacidade a ponto de não ter misericórdia com o desavisado que entra sem convite. Com sorte, os patrulheiros o levam discretamente para fora; se o pegam bisbilhotando, morre. A mata é densa, de araucárias, cedros e imbuias, e nela rondam lobos, tigres e mantícoras; na beira das Montanhas Morânicas há aranhas gigantes e, contam, um casal de dragões púrpura. É ali que fica a província élfica de Guaimbar.$t$, NULL, false),
($t$floresta-de-tambar$t$, $t$Floresta de Tambar$t$, $t$ludgrim$t$, NULL, $t$Tambar seria igual às suas irmãs Siltam e Kender, se não tivesse abrigado os seguidores e os demônios da Seita durante a guerra. As marcas desse tempo ainda estão longe de sumir, apesar do esforço do reino, e o povo da região conta muitas lendas sobre ruínas e artefatos malditos escondidos ali.
As mantícoras são o menor dos males: na floresta cresce a Árvore Maldita, criatura que tem o aspecto de uma árvore de galhos retorcidos e poucas folhas escuras, com rostos humanos torturados no tronco, e que bebe o sangue fresco de suas vítimas. Há uma única rota segura através da mata.$t$, $t$Fala-se de uma comunidade de homens-fera, talvez bestiais, que viveria na floresta e atacaria viajantes e caravanas que tentam cortar caminho pela única rota segura. A tropa que o rei mandou verificar o local está atrasada em quase quinze dias.$t$, false),
($t$floresta-de-kender$t$, $t$Floresta de Kender$t$, $t$ludgrim$t$, NULL, $t$Kender é, com Siltam, uma das duas florestas mais importantes da história do sul. Ambas foram moradia dos elfos de Lar, e muitas ruínas antigas ainda se escondem sob suas copas.$t$, $t$Há quem diga que a poderosa Espada de Meriam está escondida em Kender ou em Siltam.$t$, false),
($t$ruinas-de-eldair$t$, $t$Ruínas de Eldair$t$, $t$ludgrim$t$, NULL, $t$Eldair foi uma cidade élfica ancestral no Vale de Sumuta, destruída pelos orcos de Druai-Rir na grande invasão do sul. Foi ali que os exércitos de Donatar e Eredil alcançaram os orcos e os cercaram dentro das próprias ruínas durante todo um inverno. Na primavera de 1114 D.C., famintos, os orcos atacaram o acampamento das Três Bandeiras e foram desbaratados, mas o príncipe Donatar morreu naquele dia.
A cidade nunca foi reconstruída, e o caminho até ela foi abandonado e esquecido. Sua lembrança ficou para as canções dos bardos e para que os elfos não voltem a ser pegos de surpresa.$t$, $t$Aventureiros de palavra duvidosa contam que Enl'Idair, como chamam a velha cidade, esconde tesouros de outras eras e perigos piores que fantasmas.$t$, false),
($t$rio-galatel$t$, $t$Rio Galatel$t$, $t$ludgrim$t$, NULL, $t$O Galatel é um afluente caudaloso do rio Sevides que corre dentro de Ludgrim. É o único lugar onde vive o pigi, peixinho que é o principal ingrediente das poções de invisibilidade, e por isso magos de todos os Reinos o procuram. O reino vigia de perto a pesca e as margens, e junto à nascente ergueu o Forte Galatel para guardá-lo.$t$, NULL, false),
($t$forte-galatel$t$, $t$Forte Galatel$t$, $t$ludgrim$t$, NULL, $t$O Forte Galatel fica perto da nascente do rio de mesmo nome e existe para patrulhá-lo e proteger seu tesouro, os pequenos peixes pigi. É a segunda maior praça militar do reino e abriga quase trezentos soldados. Daqui partem as tropas que combatem as raças selvagens que tantas vezes cruzam a fronteira do sul.$t$, NULL, false),
($t$rio-darniar$t$, $t$Rio Darniar$t$, $t$ludgrim$t$, NULL, $t$O Darniar é um grande rio que atravessa todo o reino de Ludgrim desde as Montanhas Morânicas e vai alimentar o rio Sevides.$t$, NULL, false),
($t$montanhas-moranicas$t$, $t$Montanhas Morânicas$t$, $t$ludgrim$t$, NULL, $t$As Montanhas Morânicas fecham o sul de Ludgrim e separam o reino de Lar do resto de Tagmar. Na face voltada para dentro do reino, em algum ponto da parte leste, vive uma colônia de anões tidos por cidadãos de Ludgrim; para fora das fronteiras há tribos de bestiais e de orcos. Foi delas que desceu, sob Druai-Rir, a horda que devastou o sul por volta de 1100 D.C.
Nos picos fazem ninho águias gigantes e águias douradas, estas mais perto da Floresta de Lar. Novas minas têm sido abertas nessas montanhas nos últimos anos.$t$, NULL, false),
($t$montanhas-xarar$t$, $t$Montanhas Xarar$t$, $t$ludgrim$t$, NULL, $t$As Montanhas Xarar são a fronteira natural entre Âmiem, Levânia e Ludgrim. O inverno ali é rigoroso, de nevascas constantes. No sopé ficam os pomares de candre, noz que moída dá uma farinha fina, usada nas massas leves e folhadas da cozinha élfica.$t$, $t$Conta uma história sombria que o bloco de cristal onde o demônio Morrigalti foi aprisionado está escondido numa das cavernas destas montanhas.$t$, false),
($t$colinas-de-carta$t$, $t$Colinas de Cartã$t$, $t$ludgrim$t$, NULL, $t$As colinas de Cartã ficam junto à Vila Timor e são o único lugar onde crescem os arbustos espinhosos da meelberne, fruta de que se destila o meelbernil, a bebida dos bardos.$t$, NULL, false),
($t$estrada-do-rei$t$, $t$Estrada do Rei$t$, $t$ludgrim$t$, NULL, $t$A Estrada do Rei foi inaugurada há pouco e liga Donatar à cidade de Tanue, em Eredra, prometendo mais contato entre os dois reinos. É a maior das estradas que Ludgrim vem abrindo para fazer correr mercadorias e notícias, e à sua beira nasceu a cidade de Serfa.$t$, NULL, false),
($t$ordem-do-alvorecer$t$, $t$Ordem do Alvorecer$t$, $t$ludgrim$t$, NULL, $t$A Ordem do Alvorecer é a maior ordem sacerdotal dedicada a Selimom em todo o mundo. Dizem que sua casa fica a noroeste da capital, em algum ponto da Floresta de Laudis, mas poucos sabem o caminho.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$darniar$t$, $t$Rei Darniar$t$, $t$Meio-elfo$t$, $t$Rei de Ludgrim$t$, NULL, NULL, $t$ludgrim$t$, $t$donatar$t$, $t$Darniar subiu ao trono depois da morte do pai, Eredil, o primeiro rei de Ludgrim, e tem conduzido o reino a passos largos para a prosperidade. É conhecido em quase todo o Mundo Conhecido como rei justo e digno, e suas palavras são respeitadas em muitas cortes; essa fama facilita muito o comércio do reino.
É gentil, educado e de bom caráter, e seu carisma faz fácil confiar no que diz. Governa ouvindo o conselho e raramente decide contra a maioria dele. Defende com orgulho o sangue de seu povo: "Bendito seja todo meio-elfo, pois reúne em um só o melhor das duas mais poderosas raças de Tagmar."$t$, NULL, false),
($t$nidal$t$, $t$Nidal$t$, $t$Elfo dourado$t$, $t$Conselheiro-Mor de Ludgrim$t$, NULL, NULL, $t$ludgrim$t$, $t$donatar$t$, $t$Nidal é um elfo dourado de Âmiem que está em Ludgrim desde a fundação do reino. Foi tutor de Eredil na diplomacia e seu conselheiro, ajudou a unir o lud numa só língua e trouxe ao reino o alfabeto de Malim. Hoje lidera o conselho de Darniar e é o primeiro a ser ouvido antes de qualquer decisão.
Culto, polido e calmo, sabe lidar com gente e ser firme quando é preciso. Cuida de todos os contatos de Ludgrim com os outros reinos, negocia rotas de comércio e é recebido com honra nas cortes vizinhas. Diz-se que é o grande nome por trás de Darniar.$t$, NULL, false),
($t$eredil$t$, $t$Eredil$t$, NULL, $t$Primeiro rei de Ludgrim$t$, NULL, NULL, $t$ludgrim$t$, $t$donatar$t$, $t$Eredil era um guerreiro e líder nato dos homens e mestiços do sul. Com o príncipe Donatar, comandou o exército que venceu os orcos no Vale de Sumuta, e em 1116 D.C. as tribos humanas e mestiças o elegeram para liderá-las, fundando Ludgrim. Sob a tutela de Nidal tornou-se um diplomata hábil; a rainha Enora de Âmiem, testemunha do acordo com os elfos de Siltam, impressionou-se com sua honradez e sua visão. Foi coroado em Donatar menos de três anos depois e mandou erguer o Grande Forte que deu origem a Agrimir.
Quando os Bankdis chegaram, tentou expulsá-los por meio de um grupo que parecia independente da Coroa, mas os pregadores já tinham adeptos dentro de sua própria corte. Com a queda de Donatar em 1157 D.C., refugiou-se em Siltam com os fiéis. É o pai de Darniar.$t$, NULL, false),
($t$donatar$t$, $t$Donatar$t$, $t$Elfo$t$, $t$Príncipe élfico de Siltam$t$, NULL, NULL, $t$ludgrim$t$, NULL, $t$Donatar, chamado Filho da Luz, foi o príncipe élfico de Siltam. Em 1112 D.C., quando os orcos ameaçavam o Último Refúgio, foi ele quem convenceu o conselho dos elfos a aceitar a ajuda dos homens e dos mestiços, e pela primeira vez na história os elfos lutaram ao lado de outra raça.
Na primavera de 1114 D.C., no Vale de Sumuta, derrotou em combate singular o chefe dos orcos e logo caiu, atingido por uma flecha envenenada. A capital de Ludgrim leva seu nome.$t$, NULL, false),
($t$galadriom$t$, $t$Galadriom$t$, $t$Elfo$t$, $t$Líder dos elfos de Siltam$t$, NULL, NULL, $t$ludgrim$t$, NULL, $t$Galadriom reuniu sob sua liderança a maior parte dos elfos que sobreviveram à invasão dos orcos e fundou com eles uma grande comunidade na Floresta de Siltam, onde todo elfo seria bem-vindo, fosse de onde fosse, exceto os elfos sombrios.$t$, NULL, false),
($t$barao_randal$t$, $t$Barão Randal$t$, NULL, $t$Barão, governante de Serfa$t$, NULL, NULL, $t$ludgrim$t$, $t$serfa$t$, $t$O Barão Randal governa Serfa, cidade de comércio forte à beira da Estrada do Rei. Sua filha definha de uma doença que nenhum médico, curandeiro ou sacerdote conseguiu explicar.$t$, $t$Dizem que o mal da filha é maldição de uma antiga amante do barão, abandonada por ele, que se tornou maga e jurou vingança.$t$, false),
($t$agrimir$t$, $t$Agrimir$t$, NULL, $t$Comandante do Grande Forte$t$, NULL, NULL, $t$ludgrim$t$, $t$agrimir$t$, $t$Agrimir comandou os mais de quinhentos soldados enviados pelo rei Eredil para guarnecer o Grande Forte, na fronteira sul do reino. Foi o primeiro morador da fortaleza, e quando ela ganhou muros e virou cidade, recebeu o seu nome.$t$, NULL, false),
($t$druai_rir$t$, $t$Druai-Rir$t$, $t$Orco$t$, $t$Chefe guerreiro das tribos morânicas$t$, NULL, NULL, $t$ludgrim$t$, NULL, $t$Druai-Rir foi o guerreiro orco que uniu as tribos da Cadeia Morânica e as lançou contra Eldair e as vilas do sul. Morreu em 1114 D.C., no Vale de Sumuta, em combate singular contra o príncipe Donatar, e com sua morte o exército orco perdeu o ânimo e foi destroçado em poucas horas.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

UPDATE public.reinos SET capital = $t$donatar$t$ WHERE slug = $t$ludgrim$t$;



-- ── eredra ──

INSERT INTO public.reinos (slug, nome, resumo, descricao, governo, cultura, historia_recente, rumores, compartilhado) VALUES
($t$eredra$t$, $t$Eredra$t$, $t$O celeiro dos Reinos, terra sagrada de Sevides, onde o povo lavra o solo sob o jugo dos clãs volins e três Sumo Sacerdotes vivem presos na própria cidade santa.$t$, $t$Eredra é a mais populosa das nações de Tagmar. Faz divisa ao norte com Verrogar, a leste com Dantsen e o mar, ao sul com as Terras Selvagens e a oeste com Âmiem e Ludgrim. Boa parte do reino é cortada pela bacia do rio Odem, e entre os braços do Sevides, do Quiris e do Liris ficam as terras mais férteis do mundo. Ao sul, a Muralha de Goguistá fecha a passagem para as Terras Selvagens.
O verão é ameno e curto, e as chuvas da primavera bastam à lavoura. O inverno é frio e longo, com neve até o começo da primavera. No fim do outono caem chuvas tão fortes que as estradas se tornam intransitáveis, e o vento frio que sopra do sul traz neblina quase constante.
O povo de Eredra é ligado à terra como nenhum outro e tem o próprio solo por sagrado. Os eredris são humanos de origem sulista, de fala própria, o eredri, que tomou muitas palavras dos volins nos séculos de ocupação. Os volins, guerreiros, pastores e nômades das Terras Selvagens, vivem sobretudo nas cidades e nunca quiseram as terras dos eredris, só enriquecer com o trabalho deles.
Eredra produz mais da metade de todo o cereal dos Reinos, e é dessa fartura que vem sua influência: os vizinhos dependem do seu pão e por isso a tratam bem. Domina também os ofícios de manufatura e tem boas reservas de minério, quase todo extraído perto de Samor, de modo que não depende de reinos como Calco e Marana. No outono, caravanas enormes partem de Brual e Igara rumo ao Lago Denégrio, a Dantsen e a Ludgrim, castigadas pelo frio, pela neblina e pelos bandoleiros. Sempre há serviço para mercenários e aventureiros que não temam arriscar a vida.
Sevides, deus da agricultura, reina acima de todos, ao lado de seus filhos Quiris, deus do plantio, e Liris, deusa da colheita; Ganis também é muito honrada. Os Sumo Sacerdotes dos três deuses vivem em Efrim e são tidos pelo povo como Enviados Sagrados. Efrim guarda um dos maiores templos de Sevides em Tagmar.$t$, $t$O governo oficial de Eredra é um triunvirato formado pelos Sumo Sacerdotes de Sevides, Quiris e Liris: hoje Columbano, Ariberto e Imiliatânis. Sua autoridade é suprema dentro do vale de Efrim e termina nas encostas do planalto. No resto do país, o poder político e militar pertence aos Portentans volins, chefes de clã vindos das Terras Selvagens, que governam do Palácio dos Portentans, em Itéria.
O Portentã Veinor Dente Negro, bisneto de Goguistá, é o governante de fato. Os clãs que hoje ocupam o país não passam de vinte mil guerreiros espalhados pelo reino, e o vigor bárbaro deles se diluiu no contato com as cidades. A tropa de elite do Portentã, os Ursos Selvagens, é páreo para qualquer outra de Tagmar, mas tem só seiscentos homens. Se o povo eredri quisesse se libertar, poderia expulsar os volins.
Não há títulos de nobreza em Eredra. O país se divide em províncias entregues a Tu-Portentãs, e os títulos volins são de guerra mais que de governo: Portentã é general e chefe de clã; Portentani, herdeiro de clã; Pir-Portentã, general imediato; Tu-Portentã, governador e general; Vei-Portentã, capitão de até duzentos homens. O Tu-Portentã dá a ordem e manda punir quem não a cumpre; o trabalho de escrivães e coletores fica quase todo com eredris.
A justiça cabe aos sacerdotes de Sevides, Quiris e Liris, reunidos em conselho. As penas vão dos trabalhos forçados à escravidão temporária ou eterna, a dos "escravos de Cruine". Em casos extremos um único sacerdote pode sentenciar, mas não à escravidão de Cruine, que exige os três. Crimes de volins também vão aos sacerdotes, regra que Diam não tem respeitado; crimes contra volins, os volins julgam sozinhos. Matar um eredri depois de ter a honra insultada conta como crime contra um volim, e a pena é a morte ou lutar de três a cinco vezes nas arenas.
As relações com os vizinhos são amigáveis, por causa do cereal. A exceção é Dantsen, que mandou embaixada a Efrim e a Itéria para saber se Eredra pretende entrar em guerra ao lado de Verrogar. O Portentã negou, mas os volins não são conhecidos pela franqueza.$t$, $t$O ano do eredri gira em torno da lavoura. Na primavera trata-se a terra e planta-se; no verão curto cuida-se da plantação e assiste-se aos jogos nas arenas; no outono colhe-se e vende-se a safra, que precisa seguir viagem antes das chuvas do fim da estação; no inverno consertam-se as ferramentas da próxima safra. Os feriados de Sevides, Liris e Quiris são dias de grandes festas.
A maioria não aceita um estrangeiro pisando a terra de plantio, porque acredita que isso anula as bênçãos de Sevides, e por isso o eredri parece antipático a quem chega. Nas cidades o povo é ordeiro e acolhedor, exceto em Efrim, onde nenhum morador admite intruso.
Desconfia-se de toda magia que não venha de um sacerdote nem ajude a safra, e essa antipatia já levou muitos magos às arenas. Por isso há poucos magos no interior; nas grandes cidades há tantos quanto no norte, e em Brual, a Cidade das Torres, muito mais.
Nas arenas lutam gladiadores, monstros, animais e condenados. As grandes ficam nas cidades principais; as das cidades pequenas são de madeira ou aproveitam algum acidente do terreno que proteja quem assiste. Companhias ricas e influentes treinam gladiadores e capturam feras para os jogos, que se pagam com o que se cobra na entrada. Os jogos são diversão dos volins mais que dos eredris, mas quem trabalha para um volim faz bem em assistir: dizer que não gosta já custou a vida de muitos, e a justiça volim raramente condena quem mata para defender a honra. Por isso as arenas vivem cheias, mas pouco animadas, e não é raro ver aventureiros do norte arriscando a vida ali por riqueza e fama entre os volins.
As execuções também se fazem nas arenas lotadas: o condenado é amarrado pelos pés a uma parelha de cavalos, que correm e saltam sobre uma cerca baixa cravada de pontas de ferro. Às vezes é posto a lutar contra monstros até cair.$t$, $t$Depois da chegada dos moldas ao norte de Tagmar, a terra que hoje é Eredra foi por muito tempo terra de ninguém, com aldeias de lavradores ao longo do Sevides, do Quiris e do Odem. Os verrogaris chamavam esse povo de eredris e o tinham por fraco e covarde, avesso à guerra, vivendo de trocar cereais por animais de carga, de lavra e de abate. Os ataques dos bárbaros do sul do Quiris obrigaram as vilas do norte e do sul a se unir, e desse pacto nasceu Eredra: um povo forte e temido, que nunca buscou conquistas e só defendeu suas fronteiras.
Não se sabe quando se deu a união nem que governo ela teve. Registros de Saravossa de 930 D.C. falam de um imperador dos eredris; os da própria Eredra, que já eram poucos, foram destruídos pela Seita por motivos que ninguém conhece.
Em 1020 D.C. o lavrador Agidulfo, que anunciava ao povo o tempo de plantar e colher a mando de Sevides, escapou de uma tentativa de assassinato dos governantes de Itéria, e a revolta do povo o pôs no poder como primeiro governante teocrata. O rio Itéria passou a se chamar Sevides. Em 1111 a sacerdotisa Teodolinda fundou a cidade santa de Efrim e formou o triunvirato com os Sumo Sacerdotes de Quiris e Liris.
Em 1157 Efrim caiu, depois de nove meses de cerco, diante dos clãs volins guiados pelos Bankdis da Levânia e por monstros de toda espécie. O Sumo Sacerdote Rotario fugiu com a ajuda de aventureiros e organizou a resistência; o Sumo Sacerdote de Liris foi posto no poder como fantoche. Começou ali a longa noite da ocupação.
A resistência sobreviveu 244 anos na clandestinidade. Em 1401 o Mais Sábio a procurou, e o sacerdote Rupelte recebeu dele uma carta lacrada. Em 1406, com a magia que teria vindo dessa carta, Rupelte matou os chefes Bankdis; os clãs do sul, inimigos dos invasores, se aliaram aos eredris e destruíram o exército da Seita na maior batalha campal da história do reino. Rupelte foi aclamado governante e refez o triunvirato, e em 1407 Eredra entrou para a União. Até 1451 os Sumo Sacerdotes foram, pouco a pouco, deixando de governar para presidir cerimônias.
Em 1450 os mesmos clãs volins que ajudaram na libertação cruzaram o Quiris e tomaram as principais cidades, exceto Efrim. Saravossa não mandou socorro, e a Sumo Sacerdotisa Avena, valendo-se das intrigas sem fim entre os clãs, contratou outros volins para lutar por Eredra e declarou o reino independente. No ano seguinte a guerra acabou, e o Portentã Goguistá, chefe dos volins fiéis a Efrim, declarou-se Protetor Perpétuo do triunvirato e governante de fato. Desde então nenhum Sumo Sacerdote saiu de Efrim.
Hoje governa Veinor Dente Negro, bisneto de Goguistá. A independência de Columbano o preocupa, o General Rotario arma em segredo uma resistência, e Diam ferve contra a guarda volim. Veinor pensa em depor Columbano, mas teme o levante; pensa em dar mais poder ao triunvirato, mas acha que isso seria o fim da supremacia volim.$t$, $t$Corre por toda a nação que Eredra logo vai se levantar contra os volins. O medo já chegou às guardas volins, e muitos guerreiros pensam em voltar para o sul do Quiris; mas abandonar o posto é crime de morte, e os comandantes pagam estrangeiros para caçar os desertores.
Dizem que os volins trazem das Terras Selvagens um artefato mágico de grande poder, que daria força nova aos usurpadores. Ninguém sabe o que é nem de onde vem, e há quem jure que é só mentira para acalmar as tropas.
Chegam das Terras Selvagens notícias de um Portentã do extremo sul que une clãs e os empurra cada vez mais para o norte. Chamam-no de Grã-Portentã, título que nunca existiu. Se ele atacar a Muralha de Goguistá, haverá guerra. Há quem diga que é um mago poderoso nascido em Brual, mas ninguém conhece mago volim de tamanho poder.
Sabe-se que uma princesa verrogari vive em Efrim, e ninguém diz por quê. Seria a garantia de algum tratado? Dantsen desconfia de uma aliança de Eredra com Verrogar e mandou embaixada a Efrim e a Itéria; o Portentã negou tudo, mas os volins não são conhecidos pela franqueza.$t$, false)
ON CONFLICT (slug) DO UPDATE SET descricao = EXCLUDED.descricao, governo = EXCLUDED.governo, cultura = EXCLUDED.cultura,
  historia_recente = EXCLUDED.historia_recente, rumores = EXCLUDED.rumores, resumo = EXCLUDED.resumo;

INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$efrim$t$, $t$Efrim$t$, $t$eredra$t$, true, NULL, $t$O triunvirato dos Sumo Sacerdotes: Columbano (Sevides), Ariberto (Quiris) e Imiliatânis (Liris)$t$, $t$Sevides, Quiris e Liris. Tem um dos maiores templos de Sevides em Tagmar e templos belíssimos dos outros dois.$t$, $t$Vive dos templos e da sede do triunvirato; os cobradores de impostos saem de lá escoltados pela guarda da cidade.$t$, $t$Efrim é a capital sagrada e proibida de Eredra, fundada por Teodolinda em 1111 D.C. Fica num vale de encostas abruptas, com uma só entrada ao sul e outra ao norte, ambas fáceis de defender. No centro há um lago que garante água em caso de cerco, e numa ilha no meio dele ergue-se o grande palácio do governo.
Nenhum estrangeiro, mago ou "escravo de Cruine" pode entrar, nem mesmo os volins. A pena é a morte, a única que a justiça eredri prevê, e são raríssimos os invasores poupados para servir como escravos de Cruine. Dentro do vale a autoridade do triunvirato é suprema; termina nas encostas do planalto, e dali em diante quem governa é o Portentã de Itéria.
A cidade é guardada por mil e quinhentos guerreiros eredris da Ordem de Cavalaria dos Templos Sagrados, que protegem o triunvirato, vigiam as entradas, patrulham as ruas e escoltam os cobradores de impostos. Sacerdotes da Ordem de Sevides os ajudam a descobrir invasores. O General Rotario comanda essa guarda com mão de ferro.$t$, $t$Dizem que Rotario quer organizar a resistência contra os volins e que conta com o apoio de Ariberto, Sumo Sacerdote de Quiris.
Uma princesa verrogari vive em Efrim, sem que ninguém saiba por quê.$t$, false),
($t$iteria$t$, $t$Itéria$t$, $t$eredra$t$, false, NULL, $t$Portentã Veinor Dente Negro$t$, NULL, $t$Sede do governo volim e porto fluvial de pouco movimento, porque o Sevides não dá fundo para navios grandes; por isso a safra segue por terra até o Lago Denégrio.$t$, $t$Itéria fica a sudeste de Efrim, na margem esquerda do rio Sevides, e é a capital de fato de Eredra. É a cidade mais antiga do reino de que se tem notícia: dela os governantes antigos tentaram mandar matar Agidulfo, e o rio que a banha também se chamava Itéria antes de ser rebatizado em honra de Sevides.
No Palácio dos Portentans, antiga residência de verão dos sacerdotes, vive hoje o Portentã Veinor Dente Negro, bisneto de Goguistá. Dali se governa todo o país fora do vale de Efrim.
No bairro leste está a guilda de ladrões da cidade, tão antiga quanto ela. Seu chefe, Isaurio, também é muito velho e procura quem o suceda à altura, enquanto a guilda enfrenta a invasão dos Sombras Mortais, os assassinos de Brual.$t$, NULL, false),
($t$brual$t$, $t$Brual$t$, $t$eredra$t$, false, NULL, $t$Tu-Portentã Eguiardo Barba Vermelha$t$, NULL, $t$Cidade de comércio, sede ou filial de muitas companhias mercantis, a maioria planenses. De lá parte a maior parte das caravanas de cereal rumo ao Lago Denégrio.$t$, $t$Brual fica onde o rio Odem se divide em Quiris e Sevides e é conhecida como a Cidade das Torres. Vivem nela muitos estrangeiros e mais magos do que em qualquer outra cidade de Eredra, e suas torres se espalham por todas as ruas.
Os magos de Brual vivem fechados. Qualquer morador sabe apontar a torre de um deles, mas poucos podem dizer que o viram em pessoa. As guerras entre eles não são raras e às vezes deixam marcas estranhas, como as criaturas subterrâneas que começaram a aparecer e assustam o povo.
O Tu-Portentã Eguiardo Barba Vermelha anda inquieto. A guilda de assassinos Sombras Mortais, comandada por Teo, cresce a olhos vistos; as criaturas das profundezas teriam sido soltas pelo mago Raumer numa obra mágica malograda; e seu subordinado Haraldo Barba Bifurcada cobiça seu posto. Para piorar, roubaram sua espada mágica, "Dente de Dragão".$t$, $t$Eguiardo desconfia de todos à sua volta e está contratando aventureiros estrangeiros para achar a "Dente de Dragão".
Há quem diga que o Grã-Portentã do extremo sul é um mago nascido em Brual.$t$, false),
($t$diam$t$, $t$Diam$t$, $t$eredra$t$, false, NULL, $t$Dongur Queixo Azul, anão administrador$t$, NULL, $t$Fornece peixe de mar e frutos do mar ao reino.$t$, $t$Diam fica no alto de um penhasco, na foz do rio Liris. Os barcos de pesca ficam numa prainha ao pé do rochedo, e as cargas sobem até a cidade em engenhosos elevadores manejados por anões, dentro de casas fechadas onde ninguém mais entra.
Foi em Diam que se juntou a resistência contra a Seita, e o povo de lá ainda é o mais rebelde de Eredra. Os cidadãos se queixam dos abusos da guarda volim do Vei-Portentã Bremer Pé Errado, e a cidade nem respeita a regra de que crimes de volins sejam julgados pelos sacerdotes. Muitos pedem ao administrador Dongur Queixo Azul que se alie ao General Rotario.
Ao sul, o Pântano do Delta se encheu de monstros que rondam as muralhas à noite. Há pouco tempo um deles derrubou boa parte da muralha. Ninguém viu direito o que era, e quem chegou perto o bastante para ver não sobreviveu.$t$, NULL, false),
($t$igara$t$, $t$Igara$t$, $t$eredra$t$, false, NULL, $t$Tu-Portentã Herigar Sem-Frio$t$, NULL, $t$Cidade de comércio e passagem obrigatória das caravanas que seguem para o Lago Denégrio.$t$, $t$Igara é uma importante cidade comercial no norte de Eredra, por onde passam todas as caravanas que rumam ao Lago Denégrio. Ali está a maior tropa volim do reino, quatro mil homens sob o Tu-Portentã Herigar Sem-Frio.
Herigar pensa sobretudo em cobrar os impostos e separar a parte dele. Enquanto isso, a cidade afunda numa onda de crimes misteriosa.$t$, $t$Dizem que os crimes de Igara são obra de Tonodorico, mago tão misterioso quanto eles.$t$, false),
($t$samor$t$, $t$Samor$t$, $t$eredra$t$, false, NULL, $t$Tu-Portentã Egil Cabeça-de-Ferro$t$, NULL, $t$Comércio e minério: de seus arredores sai quase todo o minério extraído em Eredra.$t$, $t$Samor é uma cidade comercial de tamanho médio, fortificada há pouco por causa da guerra entre Verrogar e Dantsen. Importa muito ao reino, porque das suas vizinhanças sai quase todo o minério de Eredra.
O Tu-Portentã Egil Cabeça-de-Ferro tem mil guerreiros sob seu comando. Nascido nas Terras Selvagens, sente falta das lutas e da vida marcial do seu povo.$t$, $t$Dizem que Egil negocia em segredo com Dantsen para levar seus homens à guerra. Se o fizer, Veinor Dente Negro o terá por traidor e inimigo para sempre.$t$, false),
($t$tanue$t$, $t$Tanue$t$, $t$eredra$t$, false, NULL, $t$Vei-Portentã Naranco, o Navegador$t$, NULL, NULL, $t$Tanue é uma cidade-fortaleza que guarda a fronteira de Eredra com Ludgrim. Duzentos homens do Vei-Portentã Naranco, "o Navegador", vivem ali com suas famílias.
Há pouco Naranco teve de deixar o torreão da fortaleza por causa de supostas assombrações. Metade da comunidade está assustada e discute o que fazer; a outra metade ri do volim, com o cuidado de não fazê-lo na frente dele.$t$, $t$Naranco conta que alguns riram dele, entraram no torreão e nunca mais saíram.$t$, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$muralha-de-goguista$t$, $t$Muralha de Goguistá$t$, $t$eredra$t$, NULL, $t$A Muralha de Goguistá corre ao longo da fronteira natural que os montes formam entre Eredra e o norte das Terras Selvagens, desde as Montanhas Morânicas até o litoral leste, abaixo da foz do rio Quiris. Guarda o reino dos clãs do sul e também dos ciclopes que aterrorizavam os camponeses de Agrimir.$t$, $t$Se o Grã-Portentã do extremo sul atacar a muralha, dizem, haverá guerra em Eredra.$t$, false),
($t$pantano-do-delta$t$, $t$Pântano do Delta$t$, $t$eredra$t$, NULL, $t$O Pântano do Delta fica entre os rios Sevides e Liris, perto de Diam. Hoje está infestado de monstros de todo tipo e tamanho, que saem à noite para rondar a cidade. Um deles derrubou parte da muralha de Diam, e ninguém que o tenha visto de perto sobreviveu para contar.$t$, NULL, false),
($t$rio-sevides$t$, $t$Rio Sevides$t$, $t$eredra$t$, NULL, $t$O Sevides é o rio mais volumoso dos Reinos Civilizados e corre no extremo sul deles, por Eredra. Chamava-se Itéria até ser rebatizado em honra do deus que salvou os eredris da fome no tempo de Agidulfo. Recebe as águas do Degelo, do Brimir, do Darniar e do caudaloso Galatel, este em Ludgrim, onde vive o peixe pigi, tão buscado pelos magos para as poções de invisibilidade.
Itéria fica na sua margem esquerda. O rio não dá fundo para navios grandes, e por isso a safra de Eredra viaja por terra até o Lago Denégrio.$t$, NULL, false),
($t$rio-odem$t$, $t$Rio Odem$t$, $t$eredra$t$, NULL, $t$O Odem banha boa parte de Eredra, e sua bacia dá à terra uma fertilidade que não se acha em outro lugar. Ao longo dele viviam as primeiras aldeias de lavradores eredris. Em Brual, o rio se divide em Quiris e Sevides.$t$, NULL, false),
($t$rio-quiris$t$, $t$Rio Quiris$t$, $t$eredra$t$, NULL, $t$O Quiris leva o nome do deus do plantio e marca, no sul, o limite entre Eredra e as terras dos clãs volins. Foi dos bárbaros de além do Quiris que as aldeias eredris se uniram para se defender, e foi cruzando esse rio que os volins tomaram as cidades em 1450. A Muralha de Goguistá termina no litoral, logo abaixo da sua foz.$t$, $t$Os guerreiros volins que temem um levante eredri falam em voltar para o sul do Quiris, onde se sentem seguros.$t$, false),
($t$rio-liris$t$, $t$Rio Liris$t$, $t$eredra$t$, NULL, $t$O Liris leva o nome da deusa da colheita e corre para o mar, onde Diam se ergue sobre o penhasco da foz. Entre ele e o Sevides fica o Pântano do Delta, e as terras planas que os braços dos rios isolam junto ao mar são tidas como as mais férteis do mundo.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$columbano$t$, $t$Columbano$t$, $t$Humano$t$, $t$Sumo Sacerdote de Sevides$t$, $t$Sevides$t$, $t$Velho, mas ainda vigoroso$t$, $t$eredra$t$, $t$efrim$t$, $t$Columbano é o Sumo Sacerdote de Sevides e o mais velho do triunvirato. Os eredris o admiram e o povo de Efrim o adora, porque governou a cidade santa com sabedoria, reforçou sua segurança e fortaleceu as únicas forças armadas genuinamente eredris.
É sábio o bastante para sentir que a hora da revolta ainda não chegou. Sua independência preocupa o Portentã Veinor, que pensa em depô-lo, mas teme o levante que isso provocaria.$t$, $t$Dizem que faz vista grossa, ou dá apoio calado, à resistência armada que o General Rotario vem montando.$t$, false),
($t$ariberto$t$, $t$Ariberto$t$, $t$Humano$t$, $t$Sumo Sacerdote de Quiris$t$, $t$Quiris$t$, $t$Meia-idade$t$, $t$eredra$t$, $t$efrim$t$, $t$Ariberto é o Sumo Sacerdote de Quiris e deve se tornar o homem mais influente do triunvirato quando Columbano morrer. Acredita que chegou a hora de o povo eredri se levantar contra os invasores e não aceita a cautela extrema de Columbano.$t$, $t$Contam que apoia em segredo os planos de Rotario contra os volins.$t$, false),
($t$imiliatanis$t$, $t$Imiliatânis$t$, $t$Meio-elfo$t$, $t$Sumo Sacerdotisa de Liris$t$, $t$Liris$t$, NULL, $t$eredra$t$, $t$efrim$t$, $t$Imiliatânis é a Sumo Sacerdotisa de Liris, meia-elfa bela e misteriosa, de vida recatada e intenções que ninguém conhece. Seus sumiços frequentes preocupam Columbano, que teme que ela esteja saindo de Efrim às escondidas, o que despertaria a ira dos volins.$t$, $t$Templos de Liris em boa parte de Eredra anunciam aparições milagrosas de Imiliatânis.$t$, false),
($t$rotario$t$, $t$General Rotario$t$, $t$Humano$t$, $t$Comandante da Ordem de Cavalaria dos Templos Sagrados$t$, NULL, NULL, $t$eredra$t$, $t$efrim$t$, $t$Rotario é militar de carreira, duro e às vezes cruel com seus subordinados. Comanda com mão de ferro a guarda de Efrim e fez da Ordem de Cavalaria dos Templos Sagrados uma força temida. Leva o mesmo nome do Sumo Sacerdote que fugiu de Efrim em 1157 e organizou a primeira resistência.
Com o apoio calado de Columbano, ou ao menos com sua vista grossa, começou a erguer uma resistência armada contra os volins. Em Diam, muitos pedem que o administrador Dongur se alie a ele.$t$, $t$Corre que Ariberto, Sumo Sacerdote de Quiris, está do seu lado.$t$, false),
($t$veinor_dente_negro$t$, $t$Veinor Dente Negro$t$, $t$Humano$t$, $t$Portentã, governante de fato de Eredra$t$, NULL, NULL, $t$eredra$t$, $t$iteria$t$, $t$Veinor Dente Negro é o Portentã volim que governa Eredra do Palácio dos Portentans, em Itéria. Bisneto de Goguistá, cresceu ao sul do Quiris combatendo outros clãs, e por isso é rude, forte e pouco afeito ao trabalho de governo. É sábio o bastante, porém, para saber o quanto ele importa, e o quanto importa manter vivo o espírito guerreiro dos volins.
Não conseguiu pôr os seus no serviço do Estado, e os ofícios do governo seguem quase todos nas mãos de eredris. Comanda os Ursos Selvagens, tropa de elite de seiscentos homens que é páreo para qualquer outra de Tagmar. Prepara o filho mais velho para sucedê-lo, mandando-o lutar nas guerras tribais das Terras Selvagens e pondo-o, às vezes, ao lado de Emiriano.$t$, NULL, false),
($t$emiriano$t$, $t$Emiriano$t$, $t$Humano$t$, $t$Conselheiro do Portentã para assuntos de governo$t$, NULL, NULL, $t$eredra$t$, $t$iteria$t$, $t$Emiriano é um eredri de origem humilde que subiu no governo do reino por talento próprio. Veinor o descobriu assim que chegou a Itéria e fez dele seu braço direito. Franzino e discreto a ponto de irritar o Portentã, responde aos pedidos de conselho falando-lhe direto ao ouvido, e nunca em público.
Quem chegou a ouvir esses conselhos diz que são sempre sábios. Uns o têm por homem misterioso; outros, só por muito tímido.$t$, NULL, false),
($t$isaurio$t$, $t$Isaurio$t$, NULL, $t$Chefe da guilda de ladrões de Itéria$t$, NULL, $t$Muito velho$t$, $t$eredra$t$, $t$iteria$t$, $t$Isaurio comanda a guilda de ladrões do bairro leste de Itéria, tão antiga quanto a cidade. Está velho e procura alguém à altura para sucedê-lo, o que se torna urgente com a invasão dos Sombras Mortais de Brual.$t$, NULL, false),
($t$eguiardo_barba_vermelha$t$, $t$Eguiardo Barba Vermelha$t$, $t$Humano$t$, $t$Tu-Portentã de Brual$t$, NULL, NULL, $t$eredra$t$, $t$brual$t$, $t$Eguiardo Barba Vermelha governa Brual. É um guerreiro forte e rude, de todo deslocado na vida da cidade, e com tantos problemas à volta se vê forçado a aceitar ajuda estrangeira, sobretudo para recuperar sua espada mágica "Dente de Dragão", que lhe roubaram.
Não vê a hora de estourar uma guerra, para soltar a violência que segura à força e passar uma boa temporada longe de Brual.$t$, NULL, false),
($t$haraldo_barba_bifurcada$t$, $t$Haraldo Barba Bifurcada$t$, $t$Humano$t$, $t$Subordinado do Tu-Portentã de Brual$t$, NULL, NULL, $t$eredra$t$, $t$brual$t$, $t$Haraldo Barba Bifurcada serve sob Eguiardo Barba Vermelha em Brual e mostra interesse crescente pelo posto do seu senhor.$t$, NULL, false),
($t$teo$t$, $t$Teo$t$, NULL, $t$Chefe dos Sombras Mortais$t$, NULL, NULL, $t$eredra$t$, $t$brual$t$, $t$Teo comanda os Sombras Mortais, a guilda de assassinos de Brual, que cresce dentro da cidade e já avança sobre a guilda de ladrões de Itéria.$t$, NULL, false),
($t$raumer$t$, $t$Raumer$t$, NULL, $t$Mago$t$, NULL, NULL, $t$eredra$t$, $t$brual$t$, $t$Raumer é um mago arrogante de Brual.$t$, $t$Dizem que foi ele quem soltou as criaturas subterrâneas que assustam Brual, num acidente com uma obra mágica.$t$, false),
($t$dongur_queixo_azul$t$, $t$Dongur Queixo Azul$t$, $t$Anão$t$, $t$Administrador de Diam$t$, NULL, $t$Velho$t$, $t$eredra$t$, $t$diam$t$, $t$Dongur Queixo Azul é o velho anão que negociou com Goguistá, em pessoa, a rendição de Diam. Veinor o considera amigo, e Dongur usa essa amizade em favor da cidade.
Sabe, porém, que logo terá de escolher um lado: o dos invasores ou o da resistência, que cresce até em Diam. Enquanto isso, precisa dar conta dos monstros do Pântano do Delta, que já romperam a muralha.$t$, NULL, false),
($t$bremer_pe_errado$t$, $t$Bremer Pé Errado$t$, $t$Humano$t$, $t$Vei-Portentã, comandante da guarda volim de Diam$t$, NULL, NULL, $t$eredra$t$, $t$diam$t$, $t$Bremer Pé Errado comanda a guarda volim de Diam, e os abusos dos seus homens são a maior queixa da cidade.$t$, NULL, false),
($t$herigar_sem_frio$t$, $t$Herigar Sem-Frio$t$, $t$Humano$t$, $t$Tu-Portentã de Igara$t$, NULL, NULL, $t$eredra$t$, $t$igara$t$, $t$Herigar Sem-Frio governa Igara e lidera a maior tropa volim de Eredra, quatro mil homens. Sua grande preocupação é cobrar os impostos e separar a parte dele.$t$, NULL, false),
($t$tonodorico$t$, $t$Tonodorico$t$, NULL, $t$Mago$t$, NULL, NULL, $t$eredra$t$, $t$igara$t$, $t$Tonodorico é um mago misterioso ligado a Igara.$t$, $t$Dizem que é ele o autor da onda de crimes que toma Igara.$t$, false),
($t$egil_cabeca_de_ferro$t$, $t$Egil Cabeça-de-Ferro$t$, $t$Humano$t$, $t$Tu-Portentã de Samor$t$, NULL, NULL, $t$eredra$t$, $t$samor$t$, $t$Egil Cabeça-de-Ferro governa Samor e comanda mil guerreiros. Nasceu nas Terras Selvagens e sente falta das lutas e da vida marcial do seu povo.$t$, $t$Dizem que negocia em segredo com Dantsen para levar seus homens à guerra, o que faria de Veinor seu inimigo para sempre.$t$, false),
($t$naranco$t$, $t$Naranco, o Navegador$t$, $t$Humano$t$, $t$Vei-Portentã de Tanue$t$, NULL, NULL, $t$eredra$t$, $t$tanue$t$, $t$Naranco, "o Navegador", comanda os duzentos homens que guardam Tanue, na fronteira com Ludgrim. Há pouco deixou o torreão da fortaleza por causa de supostas assombrações, e desde então metade da cidade o teme e a outra metade ri dele pelas costas.$t$, $t$Conta que alguns zombaram dele, entraram no torreão e nunca voltaram.$t$, false),
($t$goguista$t$, $t$Goguistá, o Conquistador$t$, $t$Humano$t$, $t$Portentã, Protetor Perpétuo do triunvirato$t$, NULL, NULL, $t$eredra$t$, NULL, $t$Goguistá foi o Portentã dos clãs volins fiéis a Efrim na guerra de 1450. Quando ela acabou, em 1451, declarou-se Protetor Perpétuo do triunvirato e tornou-se governante de fato de Eredra, mais preocupado com a paz das grandes colheitas que com um governo eredri independente. Negociou com Dongur a rendição de Diam, e a grande muralha do sul leva seu nome. É bisavô de Veinor Dente Negro.
Atribuem-lhe uma pergunta que ainda corre o reino: "Que realizações temos de fato para mostrar aos nossos filhos e netos?"$t$, NULL, false),
($t$agidulfo$t$, $t$Agidulfo$t$, $t$Humano$t$, $t$Sacerdote de Sevides, primeiro governante teocrata$t$, $t$Sevides$t$, NULL, $t$eredra$t$, NULL, $t$Agidulfo era um lavrador da margem do rio então chamado Itéria, num tempo de fome sem igual, quando os deuses caminhavam loucos por Tagmar. Mesmo sem ter o que comer, acolheu e alimentou um homem esquelético que lhe pediu ajuda. O homem sumiu na manhã seguinte, e Agidulfo sonhou que Sevides mandava o povo lançar à terra as últimas sementes, porque a colheita seria farta.
Saiu a pregar, e quem obedeceu colheu fartamente. Desde então percorria o país todos os anos anunciando o tempo de plantar e colher. Os governantes de Itéria tentaram matá-lo, o povo se revoltou, e em 1020 D.C. ele subiu ao poder como sacerdote de Sevides, o primeiro governante teocrata de Eredra. O rio foi rebatizado em honra do deus.$t$, NULL, false),
($t$teodolinda$t$, $t$Teodolinda$t$, $t$Humano$t$, $t$Sacerdotisa de Sevides$t$, $t$Sevides$t$, NULL, $t$eredra$t$, $t$efrim$t$, $t$Teodolinda, sacerdotisa de Sevides, fundou em 1111 D.C. a cidade santa e proibida de Efrim. Deu mais poder aos Sumo Sacerdotes de Quiris e Liris, seus auxiliares, e com eles formou o triunvirato que ainda hoje é o governo oficial de Eredra.$t$, NULL, false),
($t$rupelte$t$, $t$Rupelte$t$, $t$Humano$t$, $t$Sacerdote de Sevides, libertador de Eredra$t$, $t$Sevides$t$, NULL, $t$eredra$t$, NULL, $t$Rupelte era um poderoso sacerdote de Sevides quando, em 1401 D.C., a resistência foi procurada pelo Mais Sábio e ele recebeu uma carta lacrada, para ser aberta no momento certo. Em 1406, com uma magia que teria vindo dessa carta, matou todos os altos chefes Bankdis de Eredra.
Sem chefes, os Portentans invasores se dividiram, clãs do sul se aliaram aos eredris, e o exército da Seita caiu na maior batalha campal da história do reino. No fim daquele ano Rupelte foi aclamado governante e refez o triunvirato.$t$, NULL, false),
($t$avena$t$, $t$Avena$t$, $t$Humano$t$, $t$Sumo Sacerdotisa de Sevides$t$, $t$Sevides$t$, NULL, $t$eredra$t$, $t$efrim$t$, $t$Avena era Sumo Sacerdotisa de Sevides quando, em 1450 D.C., os clãs volins cruzaram o Quiris e tomaram as cidades, exceto Efrim. Saravossa não mandou o socorro pedido, e ela, valendo-se das intrigas sem fim entre os clãs, contratou outros volins para lutar por Eredra e declarou o reino independente da União.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

UPDATE public.reinos SET capital = $t$efrim$t$ WHERE slug = $t$eredra$t$;


-- A capital que já existia (Sadom) também fica marcada.
UPDATE public.cidades SET capital = true WHERE historia_id IS NULL AND slug IN ('sadom','donatar','efrim');

-- Resumo escrito pelo Mestre na história 24 vence o do livro.
UPDATE public.reinos g SET resumo = s.resumo
  FROM public.reinos s
 WHERE g.historia_id IS NULL AND s.historia_id = 24 AND s.nome = g.nome
   AND g.slug IN ('levania','ludgrim','eredra') AND coalesce(s.resumo,'') <> '';

-- Funde os rascunhos: só sai o que não tem cidade, local, pessoa, personagem
-- nem história apontando para ele.
DELETE FROM public.reinos r
 WHERE r.historia_id IN (13, 24) AND r.nome IN ('Levânia','Ludgrim','Eredra')
   AND NOT EXISTS (SELECT 1 FROM public.cidades c WHERE c.reino = r.slug)
   AND NOT EXISTS (SELECT 1 FROM public.locais l WHERE l.reino = r.slug)
   AND NOT EXISTS (SELECT 1 FROM public.npcs n WHERE n.reino = r.slug)
   AND NOT EXISTS (SELECT 1 FROM public.personagens p WHERE p.reino = r.slug)
   AND NOT EXISTS (SELECT 1 FROM public.historias h WHERE h.reino = r.slug OR h.reino_atual = r.slug OR h.reino_ids::text LIKE '%' || r.slug || '%');

COMMIT;
